-- Bartesian collections: 19 variety packs, plus 23 cocktails that only come in one.
-- Generated by tools/gen-collections-migration.mjs from supabase/catalog/collections.json;
-- don't hand-edit, regenerate.

ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name,
  spirit = EXCLUDED.spirit,
  img_box = EXCLUDED.img_box,
  img_pour = EXCLUDED.img_pour,
  description = EXCLUDED.description,
  sort_order = EXCLUDED.sort_order,
  sold_single = EXCLUDED.sold_single;

ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name,
  img = EXCLUDED.img,
  sort_order = EXCLUDED.sort_order;

-- Contents are replaced wholesale, so a refresh can also drop a flavor from a pack.
DELETE FROM collection_items WHERE collection_id IN (
  'winter-vodka-collection',
  'winter-whiskey-collection',
  'winter-tequila-collection',
  'nice-collection',
  'naughty-collection',
  'festive-collection',
  'holiday-collection',
  'long-island-collection',
  'staff-picks-collection',
  'lemon-drop-variety-pack',
  'refreshers-collection',
  'classic-cocktails-favorites',
  'rum-lovers-collection',
  'low-cal-variety-pack',
  'poolside-vibes-collection-variety-pack',
  'vodka-lovers-variety-pack',
  'gin-lovers-collection',
