INSERT INTO capsules (id, name, spirit, img_box, img_pour, description, sort_order, sold_single) VALUES
  ('frosted-ambrosia', 'Frosted Ambrosia', 'vodka', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/WinterVodkaCollection.jpg?v=1793028632', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/WinterVodkaCollectionFullAssortmentwithBox.jpg?v=1793032761', 'A nostalgic, lightly fruit-forward vodka cocktail with fruit punch, marshmallow, cherry and coconut flavors.', 1001, false),
  ('the-grinch-appletini', 'The Grinch Appletini', 'vodka', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/WinterVodkaCollection.jpg?v=1793028632', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/WinterVodkaCollectionFullAssortmentwithBox.jpg?v=1793032761', 'A shimmering, sweet and tart vodka cocktail with green apple flavors.', 1002, false),
  ('frosty-navel', 'Frosty Navel', 'vodka', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/FestiveCollection.jpg?v=1793027405', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/FestiveCollectionFullAssortmentwithBox.jpg?v=1793030238', 'A vibrant vodka cocktail with tangy orange and juicy peach flavors.', 1003, false),
  ('salted-caramel-espresso-martini', 'Salted Caramel Espresso Martini', 'vodka', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/FestiveCollection.jpg?v=1793027405', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/FestiveCollectionFullAssortmentwithBox.jpg?v=1793030238', 'A luxurious twist on a favorite, with flavors of rich coffee, buttery caramel and a hint of sea salt.', 1004, false),
  ('peach-cobbler', 'Peach Cobbler', 'whiskey', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/WinterWhiskeyCollection.jpg?v=1793028908', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/WinterWhiskeyCollectionFullAssortmentwithBox.jpg?v=1793032831', 'A sweet and sour whiskey cocktail layering flavors of peach, buttery pie crust and cinnamon.', 1005, false),
  ('brown-butter-old-fashioned', 'Brown Butter Old Fashioned', 'whiskey', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/WinterWhiskeyCollection.jpg?v=1793028908', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/WinterWhiskeyCollectionFullAssortmentwithBox.jpg?v=1793032831', 'A rich, spirit-forward sipper with flavors of indulgent browned butter, bitters and a hint of orange.', 1006, false),
  ('holiday-spiced-old-fashioned', 'Holiday Spiced Old Fashioned', 'whiskey', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/WinterWhiskeyCollection.jpg?v=1793028908', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/WinterWhiskeyCollectionFullAssortmentwithBox.jpg?v=1793032831', 'A festive twist on the classic, with flavors of orange, bitters, cinnamon and seasonal brown spices.', 1007, false),
  ('ginger-pear-noel', 'Ginger Pear Noel', 'whiskey', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/WinterWhiskeyCollection.jpg?v=1793028908', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/WinterWhiskeyCollectionFullAssortmentwithBox.jpg?v=1793032831', 'A sweet blend of ripe pear and lime juices plus a kick of fiery ginger flavor.', 1008, false),
  ('peary-christmas', 'Peary Christmas', 'tequila', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/FestiveCollection.jpg?v=1793027405', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/FestiveCollectionFullAssortmentwithBox.jpg?v=1793030238', 'An elegant tequila cocktail with sweet pear, citrus and delicate almond flavors.', 1009, false),
  ('mistletoe-margarita', 'Mistletoe Margarita', 'tequila', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/WinterTequilaCollection.jpg?v=1793028419', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/WinterTequilaCollection1_4b935ae5-c54c-478f-918a-39745bafc004.jpg?v=1793032688', 'Jammy pomegranate and baking spice flavors for the perfect seasonal margarita.', 1010, false),
  ('jollypeno-margarita', 'Jollypeño Margarita', 'tequila', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/WinterTequilaCollection.jpg?v=1793028419', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/WinterTequilaCollection1_4b935ae5-c54c-478f-918a-39745bafc004.jpg?v=1793032688', 'A margarita bursting with flavors of vibrant pineapple, zesty lime and a kick of jalapeño.', 1011, false),
  ('berry-and-bright', 'Berry & Bright', 'tequila', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/FestiveCollection.jpg?v=1793027405', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/FestiveCollectionFullAssortmentwithBox.jpg?v=1793030238', 'A sweet, refreshing tequila cocktail with juicy blueberry, zesty lemon and a hint of cozy cardamom flavor.', 1012, false),
  ('winter-pear-adise', 'Winter Pear-adise', 'gin', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/NiceCollection.jpg?v=1793028004', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/NiceCollectionFullAssortmentwithBox.jpg?v=1793030322', 'A sweet and tart gin cocktail, blending flavors of juicy pear, earthy sage and a twist of lime.', 1013, false),
  ('yuletide-hurricane', 'Yuletide Hurricane', 'rum', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/NaughtyCollection.jpg?v=1793027788', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/NaughtyCollectionFullAssortment3.jpg?v=1793030273', 'A fruity, tropical rum cocktail with added shimmer.', 1014, false),
  ('tennessee-iced-tea', 'Tennessee Iced Tea', 'multi', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/LIITCollectionVarietyShot_551c6aba-5b5f-4515-8343-4673ccad72ba.jpg?v=1784321092', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/Iced_Tennessee_Hawaiian_Georgia_Peach_Long_Beach_Iced_Teas_Group.jpg?v=1784128564', 'Smooth and proofy, with citrus and cola flavors. Whiskey, vodka and tequila; 4-bottle makers only.', 1015, false),
  ('hawaiian-iced-tea', 'Hawaiian Iced Tea', 'multi', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/LIITCollectionVarietyShot_551c6aba-5b5f-4515-8343-4673ccad72ba.jpg?v=1784321092', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/Iced_Tennessee_Hawaiian_Georgia_Peach_Long_Beach_Iced_Teas_Group.jpg?v=1784128564', 'A tropical blend of sweet and tart, with lemon, orange and juicy passion fruit. Rum, vodka and tequila; 4-bottle makers only.', 1016, false),
  ('georgia-peach-iced-tea', 'Georgia Peach Iced Tea', 'multi', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/LIITCollectionVarietyShot_551c6aba-5b5f-4515-8343-4673ccad72ba.jpg?v=1784321092', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/Iced_Tennessee_Hawaiian_Georgia_Peach_Long_Beach_Iced_Teas_Group.jpg?v=1784128564', 'A Southern-inspired mix of sweet peach and lemon with a touch of cola flavor. Rum, vodka and tequila; 4-bottle makers only.', 1017, false),
  ('long-beach-iced-tea', 'Long Beach Iced Tea', 'multi', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/LIITCollectionVarietyShot_551c6aba-5b5f-4515-8343-4673ccad72ba.jpg?v=1784321092', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/Iced_Tennessee_Hawaiian_Georgia_Peach_Long_Beach_Iced_Teas_Group.jpg?v=1784128564', 'Vibrant and slightly tart, with cranberry and zesty lemon. Rum, vodka and tequila; 4-bottle makers only.', 1018, false),
  ('strawberry-lemon-drop', 'Strawberry Lemon Drop', 'vodka', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/Lemon_Drop_Collection_3_2026_1.jpg?v=1776703530', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/Lemon_Drop_Variety_Pack_-_Group_Shot_4.jpg?v=1776785175', 'Sweet and tart, with flavors of juicy strawberry and candied lemon.', 1019, false),
  ('blueberry-lemon-drop', 'Blueberry Lemon Drop', 'vodka', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/Lemon_Drop_Collection_3_2026_1.jpg?v=1776703530', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/Lemon_Drop_Variety_Pack_-_Group_Shot_4.jpg?v=1776785175', 'Jammy blueberry balanced with bright citrus flavor.', 1020, false),
  ('prickly-pear-lemon-drop', 'Prickly Pear Lemon Drop', 'vodka', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/Lemon_Drop_Collection_3_2026_1.jpg?v=1776703530', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/Lemon_Drop_Variety_Pack_-_Group_Shot_4.jpg?v=1776785175', 'Prickly pear and zesty lemon, with a hint of hibiscus flavor.', 1021, false),
  ('blue-raspberry-lemon-drop', 'Blue Raspberry Lemon Drop', 'vodka', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/Lemon_Drop_Collection_3_2026_1.jpg?v=1776703530', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/Lemon_Drop_Variety_Pack_-_Group_Shot_4.jpg?v=1776785175', 'Tangy and sweet, with blue raspberry and lemon candy-inspired flavors.', 1022, false),
  ('pineapple-passion-fruit-refresher', 'Pineapple Passion Fruit Refresher', 'vodka', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/Refreshers_-_Cocktails.jpg?v=1772472507', 'https://cdn.shopify.com/s/files/1/0038/6049/6433/files/Refresher-Packing-with-Pineapple-Passion-Fruit-Refresher-_Garnish_---Full-Usage.jpg?v=1772472507', 'Juicy pineapple and passion fruit come together in a drink that''s pure tropical bliss. Lightly caffeinated, and made to work as a mocktail too.', 1023, false)
